var GRIDINFO_RU = {
  law:{head:'Ваш короткий путь в право. ДА — если выбрать узкую область. Самый обычный путь — НЕТ.', short:'AI уже делает часть работы юристов: ищет в документах и пишет черновики. Многие боятся, что учёба была зря. Нет — но путь изменился. «Право» — это несколько очень разных работ. За людьми остаются и хорошо оплачиваются: защита данных и правила для ИИ, проверка компаний перед сделками, правила в медицине. Там вакансии платят до $319K. Помощник юриста на все руки — плохой выбор. Юрфак без ясной цели — тоже. С AI новую область можно освоить быстрее. Выберите одну — и путь станет короче.'},
  cpa:{head:'Ваш короткий путь в бухгалтерию. ДА — если выбрать узкую область. Самые обычные работы — НЕТ.', short:'AI уже делает часть работы бухгалтера: вносит операции и заполняет простые декларации. Многие боятся, что годы учёбы пропали. Не пропали — но нужен другой путь. «Бухгалтер» — это девять разных работ. Бухгалтера «на все руки» программы и ИИ заменят первым. Просто вносить операции — тоже тупик. За людьми остаются узкие области: сложные налоги, отчётность для биржи, проверка компаний перед покупкой, финансовые расследования и контролёры. Им платят $120K–$225K. Идите сразу туда — без лишней учёбы.'},
  nurse:{head:'Ваш короткий путь в медсёстры. Сестринское дело — это ДА. Самый обычный путь — НЕТ.', short:'AI уже пришёл и к медсёстрам: им пользуются три четверти из них. Но уход руками, тяжёлые пациенты и решения остаются за людьми. Важно, какой медсестрой вы станете. Будут нужны: медсестра узкой специальности, психиатрическая медсестра-практик (NP — может ставить диагноз и выписывать лекарства), медсестра-анестезист (CRNA) и медсестра на контрактах с переездами. Общая палата как конечная остановка — тупик. Старт с младшей медсестры (LPN) — плохой выбор. Семейная практика без специальности в больших городах — тоже: таких уже слишком много.'},
  fin:{head:'Ваш короткий путь в финансы. Здесь пять разных работ. Три растут. Одна — ловушка. В одну очень трудно попасть.', short:'AI уже собирает отчёты, которые раньше делал финансовый аналитик. Многие растеряны: чему теперь учиться? Мы показываем, что остаётся за людьми. «Финансовый аналитик» — это пять разных работ. Общая отчётность — ловушка: обычно платят $103,570, а мест для новичков стало меньше на 21%. Партнёру отдела по финансовому планированию платят до $276,250. Хорошо платят и в стратегических финансах, и на стыке финансов и данных. Там человек отвечает за цифру. Идите сразу туда — без лишних курсов.'},
  creator:{head:'Ваш короткий путь в авторы видео в штате. Работа в штате — это ДА. Тексты для медиа — это НЕТ.', short:'AI уже пишет черновики текстов и собирает простые видео. Креаторы растеряны: за что будут платить? Эта проверка — про креатора в штате компании, на зарплате. Не про независимого блогера. «Креатор» на работе — это пять разных работ. Бренд, где вы — вся студия, — YES. Лицо бренда — YES. Платная реклама — YES. Агентство — школа, а не конечная. Медиа и тексты — NO: самая низкая оплата из 40 вакансий в нашем разборе. И первое место, где черновик пишет ИИ. Ваше лицо и вкус AI не заменит.'},
  analyst:{head:'Ваш короткий путь в аналитики. Аналитик — это ДА. Работа только с отчётами — это НЕТ.', short:'AI и дешёвые страны уже забирают у аналитиков сборку отчётов. Многие боятся, что выучили не то. «Аналитик» — это шесть работ. Две ведут в тупик: писать требования и делать отчёты с графиками по запросу. За людьми остаются работы, где принимают решения. Аналитик продукта помогает команде решать, что менять в продукте. Стратегия и операции помогают руководителям. Инженер данных строит чистые таблицы. Платят $96K–$300K. С AI вы освоите эти навыки быстрее.'},
  dataanalyst:{head:'Ваш короткий путь в аналитики данных. Здесь четыре работы. Одна — ловушка. В двух платят за решения. Одна строит модели.', short:'Отчёты с графиками всё чаще делают AI и дешёвые страны. Многие боятся, что учили SQL зря. Не зря — его просто нужно направить иначе. «Аналитик данных» — это четыре разные работы. Отчёты по запросу — тупик: $60K–$75K на старте и 1,108 заявок на одно место для новичка. Хороший выбор — аналитик продукта: он помогает команде решать. И инженер данных, который строит чистые таблицы. Платят $96K–$300K. С AI эти навыки можно освоить быстрее.'},
  businessanalyst:{head:'Ваш короткий путь в бизнес-аналитики. Писать документы — НЕТ. Помогать руководителям принимать решения — ДА.', short:'AI уже пишет черновики документов с требованиями — главный продукт бизнес-аналитика. Многие боятся, что опыт пропал. Не пропал. Бизнес-аналитик — это две разные работы. Писать документы — тупик: начинающим платят $51K–$82K. Помогать руководителям решать (стратегия и операции) — работа, которая остаётся за людьми. Google даёт $124K–$177K. Одно название, разная работа. Выбирайте вторую.'}
};

